  1	//go:build darwin
  2	
  3	// OQ-3 runner: executes the ledger, records every event, scores every delivery, writes the evidence.
  4	
  5	package cmd
  6	
  7	import (
  8		"crypto/sha256"
  9		"database/sql"
 10		"encoding/base64"
 11		"encoding/hex"
 12		"encoding/json"
 13		"fmt"
 14		"net/http"
 15		"net/url"
 16		"os"
 17		"path/filepath"
 18		"sort"
