 27	type oq3Event struct {
 28		Scenario string `json:"scenario"`
 29		Step     int    `json:"step"`
 30		Op       string `json:"op"`
 31		Class    string `json:"class"`
 32		Label    string `json:"label"`
 33		Trial    string `json:"trial,omitempty"`
 34		Verdict  string `json:"verdict"` // pass | fail | absent | done | harness-failed
 35		Outcome  any    `json:"outcome,omitempty"`
 36		At       string `json:"at"`
 37	}
 38	
 39	type oq3Run struct {
 40		t        *testing.T
 41		sc       oq3Scenario
 42		d        *oq3Daemon
 43		s        *oq3Sandbox
 44		desk     *oq3Desktop
 45		deskLife int
 46		term     *oq3Terminal
 47		termN    int
 48		convIDs  map[string]string
 49		async    map[string]chan asyncResult
 50		marks    map[string]int
 51		// marksLabel remembers which label a held turn was sent under, per conversation handle.
 52		marksLabel map[string]string
 53		// builtBinary, when set, is the built `ollama` used by the entry arm for CLI steps.
 54		builtBinary []string
 55		// terminalHelper selects the terminal helper mode; empty is the launch function. Only the runner
 56		// controls set another mode.
 57		terminalHelper string
 58		// termRefusedAtStart records that the terminal session refused at start-up against a daemon
 59		// without chat.admission.v1 (A12), which the capability-less scenarios allow (review round 2,
 60		// finding 6).
 61		termRefusedAtStart bool
 62		// termOpenNotIdle records that a session which refused at start-up stayed open without an idle
 63		// chat (for example at a picker), which A12 also allows (review round 3, finding 4).
 64		termOpenNotIdle bool
 65		events          []oq3Event
 66		invalid         []string
 67	}
 68	
 69	// oq3PreloadDone reports whether the chat's preload under label has finished at the daemon. The
 70	// preload function (cmd/agent_tui.go:583-608, preloadAgentModelIfLocal) sends POST /api/show, POST
 71	// /api/generate and then GET /api/ps, and returns once that last request is answered; the chat's idle
 72	// proof cannot see a preload (review round 3, finding 1).
 73	func (d *oq3Daemon) preloadDone(label string) bool {
 74		gen := 0
 75		for _, c := range d.snapshot() {
 76			switch {
 77			case c.Label == label && c.Method == http.MethodPost && c.Path == "/api/generate":
 78				gen = c.Seq
 79			case gen > 0 && c.Label == label && c.Method == http.MethodGet && c.Path == "/api/ps" && c.Seq > gen:
 80				return true
 81			}
 82		}
 83		return false
 84	}
 85	
 86	// mustPreload waits for a preload started by this step to finish at the daemon; a timeout is a harness
 87	// failure, never a reason to advance.
 88	func (r *oq3Run) mustPreload(label, when string) {
 89		if !oq3WaitFor(30*time.Second, func() bool { return r.d.preloadDone(label) || r.term.hasExited() }) || !r.d.preloadDone(label) {
 90			r.harnessFail("the preload %s never finished at the daemon (POST /api/generate, then GET /api/ps, under %s); screen tail %q", when, label, tail(r.term.screen(), 800))
 91		}
 92	}
 93	
 94	// oq3RefusalReported reports whether the screen carries the refusal A12 and §8 require against a daemon
 95	// without chat.admission.v1: the daemon's version, and a name for the refusal (review round 3, finding
 96	// 3). Compared case-insensitively with white space removed, so a wrapped line still matches. The
 97	// blueprint states no exact text for the terminal (gap 7).
 98	func oq3RefusalReported(screen string) bool {
 99		j := strings.ToLower(strings.Join(strings.Fields(screen), ""))
100		if !strings.Contains(j, strings.ToLower(oq3NoAdmissionVersion)) {
101			return false
102		}
103		for _, name := range []string{"context_unavailable", "contextunavailable", "chat.admission.v1"} {
104			if strings.Contains(j, name) {
105				return true
106			}
107		}
108		return false
109	}
110	
111	func oq3NewRun(t *testing.T, sc oq3Scenario, d *oq3Daemon, s *oq3Sandbox) *oq3Run {
112		return &oq3Run{t: t, sc: sc, d: d, s: s, convIDs: map[string]string{}, async: map[string]chan asyncResult{},
113			marks: map[string]int{}, marksLabel: map[string]string{}}
114	}
115	
116	type asyncResult struct {
117		id  string
118		res oq3HTTPResult
119	}
120	
121	func oq3Label(sc string, i int, op string) string { return fmt.Sprintf("%s/%02d/%s", sc, i, op) }
122	
123	func (r *oq3Run) event(i int, st oq3Step, verdict string, outcome any) {
124		r.events = append(r.events, oq3Event{Scenario: r.sc.ID, Step: i, Op: st.Op, Class: st.Class, Label: oq3Label(r.sc.ID, i, st.Op),
125			Trial: st.Trial, Verdict: verdict, Outcome: outcome, At: time.Now().Format(time.RFC3339Nano)})
126		if verdict == "harness-failed" {
127			r.invalid = append(r.invalid, fmt.Sprintf("%s step %d %s: %v", r.sc.ID, i, st.Op, outcome))
128		}
129	}
130	
131	// execute runs every step. A harness failure stops the scenario (later steps are recorded as not
132	// run) and makes the run invalid; it is never scored as a delivery defect.
133	func (r *oq3Run) execute() {
134		for i, st := range r.sc.Steps {
135			label := oq3Label(r.sc.ID, i, st.Op)
136			switch st.Op {
137			case "terminal-await":
138				// Requests caused while a held turn completes (its tool continuations) belong to that
139				// turn, so its label stays active.
140				r.d.setLabel(r.heldLabel("terminal"))
141			case "desktop-await":
142				r.d.setLabel(r.heldLabel(st.Args["conv"]))
143			default:
144				r.d.setLabel(label)
145			}
146			if len(r.invalid) > 0 {
147				r.event(i, st, "not-run", "an earlier harness failure stopped this scenario")
148				continue
149			}
150			func() {
151				defer func() {
152					if p := recover(); p != nil {
153						r.event(i, st, "harness-failed", fmt.Sprint(p))
154					}
155				}()
156				r.step(i, st, label)
157			}()
158		}
159		if r.term != nil {
160			r.term.kill()
161		}
162		if r.desk != nil {
163			_ = r.desk.cmd.Process.Kill()
164		}
165	}
166	
167	func (r *oq3Run) harnessFail(format string, a ...any) {
168		panic(fmt.Sprintf(format, a...))
169	}
170	
171	func (r *oq3Run) step(i int, st oq3Step, label string) {
172		switch st.Op {
173		case "desktop-start":
174			r.deskLife++
175			r.desk = oq3StartDesktopNoFatal(r, r.deskLife)
176			r.event(i, st, "done", map[string]any{"life": r.deskLife})
177		case "desktop-stop":
178			if err := r.desk.stopNoFatal(); err != nil {
179				r.harnessFail("desktop stop: %v", err)
180			}
181			r.event(i, st, "done", map[string]any{"life": r.deskLife, "exited": true})
182			r.desk = nil
183		case "auth-control":
184			unauth := r.desk.doAuth(http.MethodGet, "/api/v1/settings", nil, false)
185			auth := r.desk.doAuth(http.MethodGet, "/api/v1/settings", nil, true)
186			ok := unauth.Status == http.StatusForbidden && auth.Status == http.StatusOK && strings.Contains(auth.Body, `"settings"`)
187			if !ok {
188				r.harnessFail("auth control: unauthenticated %d, authenticated %d", unauth.Status, auth.Status)
189			}
190			r.event(i, st, "done", map[string]any{"unauthenticated": unauth.Status, "authenticated": auth.Status})
191		case "legacy-fixture":
192			id := "0192f0a0-3c3d-7000-8000-0000000000aa"
193			c := oq3HelperCmd(r.s, r.d, "legacy", "OQ3_CHAT_ID="+id)
194			out, err := c.CombinedOutput()
195			if err != nil {
196				r.harnessFail("legacy fixture: %v: %s", err, out)
197			}
198			r.convIDs[st.Args["conv"]] = id
199			r.event(i, st, "done", map[string]any{"chat_id": id})
200		case "desktop-save":
201			body := map[string]any{"expected_revision": st.Args["expected_revision"],
202				"edit": map[string]any{"enabled": st.Args["enabled"] == "true", "text": oq3TextOrEmpty(st.Args["text"]), "binding": nil}}
203			res := r.desk.do(http.MethodPut, "/api/v1/instructions", body)
204			verdict := oq3ProfileVerdict(res, st.Want)
205			if verdict == "pass" {
206				verdict = r.storeCommitted(st.Want)
207			}
208			r.event(i, st, verdict, res)
209		case "desktop-draft":
210			res := r.desk.do(http.MethodPost, "/api/v1/create-chat", map[string]any{})
211			var v struct {
212				ID string `json:"id"`
213			}
214			if res.Status != 200 || json.Unmarshal([]byte(res.Body), &v) != nil || v.ID == "" {
215				r.event(i, st, "fail", res)
216				r.harnessFail("create-chat did not return an id: %d %s", res.Status, res.Body)
217			}
218			r.convIDs[st.Conv] = v.ID
219			r.event(i, st, "pass", map[string]any{"status": res.Status, "chat_id": v.ID})
220		case "desktop-turn":
221			r.desktopTurn(i, st, label)
222		case "desktop-await":
223			ch := r.async[st.Args["conv"]]
224			r.d.release(r.heldLabel(st.Args["conv"]))
225			select {
226			case ar := <-ch:
227				r.convIDs[st.Args["conv"]] = ar.id
228				r.event(i, st, "done", map[string]any{"status": ar.res.Status})
229			case <-time.After(60 * time.Second):
230				r.harnessFail("held desktop turn never completed")
231			}
232		case "desktop-reload":
233			id := r.convIDs[st.Conv]
234			if id == "" {
235				r.harnessFail("reload of unknown conversation %q", st.Conv)
236			}
237			body := map[string]any{"expected_generation": st.Args["expected_generation"], "expected_target_revision": st.Args["expected_target_revision"]}
238			res := r.desk.do(http.MethodPost, "/api/v1/chat/"+id+"/instructions/reload", body)
239			r.event(i, st, oq3ReloadVerdict(res, st.Want), res)
240		case "cli-set":
241			path := filepath.Join(r.s.tmp, fmt.Sprintf("instructions-%s-%02d.txt", r.sc.ID, i))
242			if err := os.WriteFile(path, []byte(oq3TextOrEmpty(st.Args["text"])), 0o600); err != nil {
243				r.harnessFail("write instructions file: %v", err)
244			}
245			res := oq3RunCLINoFatal(r, "instructions", "set", "--file", path, "--expected-revision", st.Args["expected_revision"])
246			verdict := "fail"
247			switch {
248			case strings.Contains(res.Output, "unknown command"):
249				verdict = "absent"
250			case res.ExitCode == 0:
251				// Blueprint §7 as resolved in continuation 14: `set` saves the file's text as an
252				// enabled profile. Exit 0 counts only when the store shows it committed.
253				verdict = r.storeCommitted(map[string]string{"revision": st.Want["revision"], "enabled": "true", "text": st.Args["text"]})
254			}
255			r.event(i, st, verdict, res)
256		case "terminal-start":
257			r.termN++
258			r.term = oq3StartTerminalNoFatal(r, fmt.Sprintf("%s-%d", r.sc.ID, r.termN), st.Args["model"])
259			preloaded := func() bool { return r.d.countLabel("POST", "/api/generate", label) >= 1 }
260			if r.sc.NoCapability {
261				r.terminalStartWithoutCapability(i, st, preloaded)
262				return
263			}
264			if !oq3WaitFor(30*time.Second, func() bool { return preloaded() || r.term.hasExited() }) || r.term.hasExited() {
265				r.harnessFail("terminal session never preloaded; screen tail %q", tail(r.term.screen(), 1500))
266			}
267			r.mustPreload(label, "of the session's model")
268			r.mustIdle("after the session started")
269			r.event(i, st, "done", map[string]any{"session": r.termN})
270		case "terminal-stop":
271			if r.termRefusedAtStart && r.term.hasExited() {
272				// The session already ended at start-up with its refusal; there is nothing to close.
273				r.event(i, st, "done", map[string]any{"session": r.termN, "exited_at_start": true})
274				r.term.kill()
275				r.term = nil
276				return
277			}
278			if r.termRefusedAtStart && r.termOpenNotIdle {
279				// The session refused and stayed open outside an idle chat, where /bye cannot be typed; the
280				// driver ends it (review round 3, finding 4).
281				r.term.kill()
282				r.event(i, st, "done", map[string]any{"session": r.termN, "ended_by_driver_after_refusal": true})
283				r.term = nil
284				return
285			}
286			r.term.typeLine("/bye")
287			if err, ok := r.term.waitExit(20 * time.Second); !ok || err != nil {
288				r.harnessFail("terminal did not exit cleanly on /bye: ok=%v err=%v", ok, err)
289			}
290			r.event(i, st, "done", map[string]any{"session": r.termN, "exited": true})
291			r.term.kill()
292			r.term = nil
293		case "entry-start":
294			// The entry arm: the built `ollama` binary with no arguments, through the launcher menu
295			// (cmd/cmd.go:2161-2260) to the agent chat, exactly as the operator starts it.
296			if len(r.builtBinary) == 0 {
297				r.harnessFail("entry arm needs the built binary (OQ3_BINARY)")
298			}
299			r.termN++
300			r.term = oq3StartTerminalWith(oq3Panic, r.s, r.d, fmt.Sprintf("%s-%d", r.sc.ID, r.termN), "", r.builtBinary, "")
301			mark := 0
302			if !oq3WaitFor(30*time.Second, func() bool { return r.term.screenContainsAfter(mark, "Chat, Code") || r.term.hasExited() }) || r.term.hasExited() {
303				r.harnessFail("launcher menu never appeared; screen tail %q", tail(r.term.screen(), 1500))
304			}
305			// Every wait is checked (review round 2, finding 5): a timeout is a harness failure.
306			r.mustQuiet("while the launcher menu is shown")
307			mark = r.term.rawLen()
308			r.term.key("\r")
309			if !oq3WaitFor(30*time.Second, func() bool {
310				return r.term.screenContainsAfter(mark, "Select model") || r.d.countLabel("POST", "/api/generate", label) >= 1 || r.term.hasExited()
311			}) || r.term.hasExited() {
312				r.harnessFail("the run-model action reached neither a model picker nor the chat; screen tail %q", tail(r.term.screen(), 1500))
313			}
314			picked := false
315			if r.d.countLabel("POST", "/api/generate", label) == 0 {
316				r.mustQuiet("while the launcher's model picker is shown")
317				r.term.key(oq3Model)
318				r.mustQuiet("after filtering the launcher's model picker")
319				r.term.key("\r")
320				picked = true
321			}
322			if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/generate", label) >= 1 || r.term.hasExited() }) || r.term.hasExited() {
323				r.harnessFail("the agent chat never preloaded after the launcher; screen tail %q", tail(r.term.screen(), 1500))
324			}
325			r.mustPreload(label, "after the launcher")
326			r.mustIdle("after the launcher reached the agent chat")
327			r.event(i, st, "done", map[string]any{"session": r.termN, "model_picker_used": picked, "binary": r.builtBinary[0]})
328		case "entry-stop":
329			mark := r.term.rawLen()
330			r.term.typeLine("/bye")
331			if !oq3WaitFor(20*time.Second, func() bool { return r.term.screenContainsAfter(mark, "Chat, Code") || r.term.hasExited() }) {
332				r.harnessFail("the launcher menu did not return after /bye; screen tail %q", tail(r.term.screen(), 1500))
333			}
334			if !r.term.hasExited() {
335				r.mustQuiet("while the launcher menu is shown again")
336				r.term.key("q")
337			}
338			if err, ok := r.term.waitExit(20 * time.Second); !ok || err != nil {
339				r.harnessFail("the launcher did not exit cleanly: ok=%v err=%v", ok, err)
340			}
341			r.event(i, st, "done", map[string]any{"session": r.termN, "exited": true})
342			r.term.kill()
343			r.term = nil
344		case "terminal-turn":
345			r.terminalTurn(i, st, label)
346		case "terminal-await":
347			lbl := r.heldLabel("terminal")
348			mark := r.marks["terminal"]
349			r.d.release(lbl)
350			r.finishTerminalTurn(lbl, r.marks["terminal-rounds"], 0, mark)
351			r.event(i, st, "done", nil)
352		case "terminal-slash":
353			r.terminalSlash(i, st, label)
354		case "store-identity":
355			r.event(i, st, r.storeIdentity(st.Want), nil)
356		case "store-events":
357			r.event(i, st, r.storeEvents(), nil)
358		default:
359			r.harnessFail("unknown op %q", st.Op)
360		}
361	}
362	
363	func (r *oq3Run) heldLabel(conv string) string { return r.marksLabel[conv] }
364	
365	func oq3TextOrEmpty(key string) string {
366		if key == "" {
367			return ""
368		}
369		return oq3Texts[key]
370	}
371	
372	// ---------------------------------------------------------------------------------------------
373	// Desktop turns.
374	
375	func (r *oq3Run) desktopTurn(i int, st oq3Step, label string) {
376		id := r.convIDs[st.Conv]
377		if id == "" {
378			id = "new"
379		}
380		body := map[string]any{"model": oq3Model, "prompt": st.Prompt}
381		if m := st.Args["model"]; m != "" {
382			body["model"] = m
383		}
384		if st.Args["think"] == "true" {
385			body["think"] = true
386		}
387		if st.Args["web_search"] == "true" {
388			body["web_search"] = true
389		}
390		if name := st.Args["attachment"]; name != "" {
391			body["attachments"] = []any{map[string]any{"filename": name, "data": base64.StdEncoding.EncodeToString([]byte("OQ3 attachment line one.\nOQ3 attachment line two.\n"))}}
392		}
393		if s := st.Args["fail"]; s != "" {
394			n, _ := strconv.Atoi(s)
395			r.d.failNext(label, n)
396		}
397		if st.Args["hold"] == "1" {
398			r.d.hold(label)
399			r.marksLabel[st.Conv] = label
400			ch := make(chan asyncResult, 1)
401			r.async[st.Conv] = ch
402			desk := r.desk
403			go func() {
404				newID, res := desk.chatBody(id, body)
405				ch <- asyncResult{id: newID, res: res}
406			}()
407			if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/chat", label) >= 1 }) {
408				r.harnessFail("held desktop turn never reached the daemon")
409			}
410			r.event(i, st, "dispatched-held", map[string]any{"conversation": st.Conv})
411			return
412		}
413		newID, res := r.desk.chatBody(id, body)
414		if newID != "" && newID != "new" {
415			r.convIDs[st.Conv] = newID
416		}
417		r.event(i, st, "done", map[string]any{"status": res.Status, "chat_id": newID, "stream_tail": tail(res.Body, 400)})
418	}
419	
420	// ---------------------------------------------------------------------------------------------
421	// Terminal turns and commands.
422	
423	// terminalStartWithoutCapability starts a session against a daemon without chat.admission.v1 (review
424	// round 2, finding 6; round 3, findings 3 and 4). A12 (blueprint §6.3) and §8 require no
425	// carrier-bearing request and a context_unavailable report naming the daemon's version; nothing
426	// requires the check to wait for a preload, or the session to stay in an idle chat. So the session may
427	// preload and go idle (the unchanged candidate does), or refuse at start-up: exiting, staying in an
428	// idle chat, or staying open elsewhere (for example at a picker). A refusal is recognised only by its
429	// report: the daemon's version and a name for the refusal (oq3RefusalReported). A session that ends at
430	// start-up without that report is a harness failure, never a refusal.
431	func (r *oq3Run) terminalStartWithoutCapability(i int, st oq3Step, preloaded func() bool) {
432		label := oq3Label(r.sc.ID, i, st.Op)
433		reported := func() bool { return oq3RefusalReported(r.term.screen()) }
434		if !oq3WaitFor(30*time.Second, func() bool { return preloaded() || r.term.hasExited() || reported() }) {
435			r.harnessFail("terminal session neither preloaded, reported the missing capability nor exited; screen tail %q", tail(r.term.screen(), 1500))
436		}
437		// A report is often the last thing a refusing process prints before it exits.
438		if reported() && !r.term.hasExited() {
439			oq3WaitFor(2*time.Second, r.term.hasExited)
440		}

431	func (r *oq3Run) terminalStartWithoutCapability(i int, st oq3Step, preloaded func() bool) {
432		label := oq3Label(r.sc.ID, i, st.Op)
433		reported := func() bool { return oq3RefusalReported(r.term.screen()) }
434		if !oq3WaitFor(30*time.Second, func() bool { return preloaded() || r.term.hasExited() || reported() }) {
435			r.harnessFail("terminal session neither preloaded, reported the missing capability nor exited; screen tail %q", tail(r.term.screen(), 1500))
436		}
437		// A report is often the last thing a refusing process prints before it exits.
438		if reported() && !r.term.hasExited() {
439			oq3WaitFor(2*time.Second, r.term.hasExited)
440		}
441		refused := func(open, idle bool) {
442			r.termRefusedAtStart = true
443			r.termOpenNotIdle = open && !idle
444			r.event(i, st, "refused-at-start", map[string]any{"session": r.termN, "exited": !open, "idle_chat": idle,
445				"preloaded": preloaded(), "screen_tail": tail(r.term.screen(), 600)})
446		}
447		exitedWithReport := func() {
448			// The output of a process that has just exited may still be draining from the terminal.
449			if !oq3WaitFor(3*time.Second, reported) {
450				r.harnessFail("terminal session exited at start-up without reporting the refusal (the daemon's version %s and context_unavailable or chat.admission.v1); screen tail %q", oq3NoAdmissionVersion, tail(r.term.screen(), 1500))
451			}
452			refused(false, false)
453		}
454		if r.term.hasExited() {
455			exitedWithReport()
456			return
457		}
458		if preloaded() {
459			r.mustPreload(label, "of the session's model")
460		}
461		// Still running: an idle chat is proved as usual; a reported refusal need not reach one.
462		if r.term.idle(15 * time.Second) {
463			if reported() && !preloaded() {
464				refused(true, true)
465				return
466			}
467			r.event(i, st, "done", map[string]any{"session": r.termN, "preloaded": preloaded(), "reported": reported()})
468			return
469		}
470		switch {
471		case r.term.hasExited():
472			exitedWithReport()
473		case reported():
474			if !r.term.quiet(600*time.Millisecond, 20*time.Second) {
475				r.harnessFail("the session reported its refusal but never went quiet; screen tail %q", tail(r.term.screen(), 800))
476			}
477			refused(true, false)
478		default:
479			r.harnessFail("terminal never proved idle after the session started without the capability, and reported no refusal; screen tail %q", tail(r.term.screen(), 800))
480		}
481	}
482	
483	// oq3RefusedTurnWait is how long a no-dispatch turn waits for any request when the session that
484	// refused at start-up cannot be typed into (it exited, or stayed open outside an idle chat).
485	const oq3RefusedTurnWait = 5 * time.Second
486	
487	func (r *oq3Run) terminalTurn(i int, st oq3Step, label string) {
488		if r.termRefusedAtStart && (r.term.hasExited() || r.termOpenNotIdle) {
489			// The session refused at start-up and cannot be typed into (it exited, or stayed open outside an
490			// idle chat). Nothing is typed; any request under this step within the wait is still captured,
491			// and the step is scored by its class (a refusal held as required).
492			time.Sleep(oq3RefusedTurnWait)
493			r.event(i, st, "no-request", map[string]any{"session": "refused at start-up", "exited": r.term.hasExited(),
494				"requests_under_step": r.d.countLabel(http.MethodPost, "/api/chat", label)})
495			return
496		}
497		rounds, _ := strconv.Atoi(st.Args["tool_rounds"])
498		if rounds > 0 {
499			r.d.setToolRounds(label, rounds)
500		}
501		if st.Args["auto_compact"] == "1" {
502			r.d.reportPromptEval(label, 30000)
503		}
504		mark := r.term.rawLen()
505		if st.Args["hold"] == "1" {
506			r.d.hold(label)
507			r.marksLabel["terminal"] = label
508			r.marks["terminal"] = mark
509		}
510		r.term.typeLine(st.Prompt)
511		if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/chat", label) >= 1 }) {
512			// No request reached the daemon: recorded, and scored by the step's class (a missing
513			// required delivery, or a refusal held as required).
514			r.mustIdle("after a turn that sent no request")
515			r.event(i, st, "no-request", map[string]any{"screen_tail": tail(r.term.screen(), 1200)})
516			return
517		}
518		if st.Args["hold"] == "1" {
519			r.marks["terminal-rounds"] = rounds
520			r.event(i, st, "dispatched-held", nil)
521			return
522		}
523		r.finishTerminalTurn(label, rounds, st.Summarisers, mark)
524		r.event(i, st, "done", nil)
525	}
526	
527	// finishTerminalTurn approves each declared tool round, then waits until every response under the
528	// label has been fully written by the daemon (review finding 8) and the chat has proved it is idle
529	// (review round 2, finding 5): the daemon finishing and the screen going quiet do not show that the
530	// chat's run has ended.
531	func (r *oq3Run) finishTerminalTurn(label string, rounds, summarisers, mark int) {
532		for k := 0; k < rounds; k++ {
533			approvalMark := mark
534			if !oq3WaitFor(30*time.Second, func() bool { return r.term.screenContainsAfter(approvalMark, "Approve once") }) {
535				r.harnessFail("tool round %d: approval prompt never appeared; screen tail %q", k+1, tail(r.term.screen(), 1500))
536			}
537			want := r.d.countLabel("POST", "/api/chat", label) + 1
538			mark = r.term.rawLen()
539			r.term.key("1")
540			if !oq3WaitFor(30*time.Second, func() bool { return r.d.countLabel("POST", "/api/chat", label) >= want }) {
541				r.harnessFail("tool round %d: continuation never reached the daemon", k+1)
542			}
543		}
544		if !oq3WaitFor(30*time.Second, func() bool {
545			n := r.d.countLabel("POST", "/api/chat", label)
546			return r.d.countSummaries(label) >= summarisers && r.d.completedLabel(label) >= n
547		}) {
548			r.harnessFail("responses under %s never completed (%d requests, %d completed, %d summaries)", label,
549				r.d.countLabel("POST", "/api/chat", label), r.d.completedLabel(label), r.d.countSummaries(label))
550		}
551		r.mustIdle("after the turn completed")
552	}
553	
554	// mustQuiet waits for the terminal to stop producing output; a timeout is a harness failure, never
555	// a reason to advance (review finding 8). It paces keystrokes into a menu or picker; it is not the
556	// proof that a turn has ended, which is mustIdle.
557	func (r *oq3Run) mustQuiet(when string) {
558		if !r.term.quiet(600*time.Millisecond, 20*time.Second) {
559			r.harnessFail("terminal did not go quiet %s; screen tail %q", when, tail(r.term.screen(), 800))
560		}
561	}
562	
563	// oq3AckMarker is typed after a command sent while a turn runs; it holds no digit, so an approval prompt
564	// (which answers 1, 2 and 3) could not act on it.
565	const oq3AckMarker = "OQACKZ"
566	
567	// mustIdle requires the chat's own proof that it is idle (oq3Terminal.idle); a timeout is a harness
568	// failure, never a reason to advance (review round 2, finding 5).
569	func (r *oq3Run) mustIdle(when string) {
570		if !r.term.idle(30 * time.Second) {
571			r.harnessFail("terminal never proved idle %s; screen tail %q", when, tail(r.term.screen(), 800))
572		}
573	}
574	
575	func (r *oq3Run) terminalSlash(i int, st oq3Step, label string) {
576		cmd := st.Args["cmd"]
577		mark := r.term.rawLen()
578		if pick := st.Args["pick"]; pick != "" {
579			r.term.typeLine(cmd)
580			if !oq3WaitFor(15*time.Second, func() bool { return r.term.screenContainsAfter(mark, pick) }) {
581				r.harnessFail("model picker never listed %s; screen tail %q", pick, tail(r.term.screen(), 1500))
582			}
583			// Every wait is checked (review round 2, finding 5); the chat must then prove it is idle, so
584			// the next step cannot start while the switch is still being applied.
585			r.mustQuiet("while the model picker lists " + pick)
586			r.term.key(pick)
587			r.mustQuiet("after filtering the model picker for " + pick)
588			r.term.key("\r")
589			// Switching model starts a preload, which the idle proof cannot see (review round 3, finding 1).
590			r.mustPreload(label, "of "+pick)
591			r.mustIdle("after picking " + pick)
592			r.event(i, st, "done", map[string]any{"picked": pick, "screen_tail": tail(r.term.screen(), 600)})
593			return
594		}
595		r.term.typeLine(cmd)
596		if st.Class == "required-refusal" {
597			// Sent while a held turn runs: nothing on screen can show the refusal, and its effect is judged
598			// by the deliveries that follow (review finding 1; round 2, finding 1). The chat must have
599			// handled the Enter before the response is released, or an approval prompt could take it
600			// (review round 3, finding 2). Keys are handled in order, so a marker typed after the Enter
601			// that reaches the input box proves the Enter was handled while the response was still held,
602			// when no approval prompt can exist. The marker is then cleared.
603			ackMark := r.term.rawLen()
604			r.term.key(oq3AckMarker)
605			if !oq3WaitFor(15*time.Second, func() bool { return r.term.screenContainsAfter(ackMark, oq3AckMarker) }) {
606				r.harnessFail("the chat did not handle %s while the turn was held (its input box never showed the marker); screen tail %q", cmd, tail(r.term.screen(), 800))
607			}
608			r.term.key("\x15")
609			r.event(i, st, "sent-while-running", map[string]any{"handled_while_held": true})
610			return
611		}
612		if st.Summarisers > 0 {
613			if !oq3WaitFor(30*time.Second, func() bool {
614				return r.d.countSummaries(label) >= st.Summarisers && r.d.completedLabel(label) >= r.d.countLabel("POST", "/api/chat", label)
615			}) {
616				r.mustIdle("after a compaction that did not complete")
617				r.event(i, st, "fail", map[string]any{"summarisers_seen": r.d.countSummaries(label), "screen_tail": tail(r.term.screen(), 1200)})
618				return
619			}
620		}
621		r.mustIdle("after " + cmd)
622		unknown := r.term.screenContainsAfter(mark, "Unknown command") || r.term.screenContainsAfter(mark, "usage: ")
623		verdict := "done"
624		switch {
625		case unknown && strings.HasPrefix(cmd, "/instructions"):
626			verdict = "absent"
627		case unknown:
628			// An existing command that printed an error or its usage did not do what the step declares.
629			r.harnessFail("%s was rejected by the terminal; screen tail %q", cmd, tail(oq3ANSI.ReplaceAllString(r.term.rawSince(mark), ""), 600))
630		case strings.HasPrefix(cmd, "/instructions"):
631			// No error was printed. The blueprint (§7) names no success output, so the screen cannot
632			// show success; the delivery after this step decides (review finding 1).
633			verdict = "no-error-seen"
634		}
635		r.event(i, st, verdict, map[string]any{"screen_tail": tail(oq3ANSI.ReplaceAllString(r.term.rawSince(mark), ""), 600)})
636	}
