639	// Operation verdicts. "absent" means the designated surface does not exist at this commit (the
640	// application's HTML fallback or an unknown command); it is a failed operation, not a harness fault.
641	
642	func oq3IsHTML(res oq3HTTPResult) bool {
643		return strings.Contains(strings.ToLower(res.ContentType), "text/html") || strings.HasPrefix(strings.TrimSpace(strings.ToLower(res.Body)), "<!doctype html")
644	}
645	
646	func oq3ProfileVerdict(res oq3HTTPResult, want map[string]string) string {
647		if oq3IsHTML(res) || res.Status == http.StatusNotFound {
648			return "absent"
649		}
650		var p struct {
651			Revision string `json:"revision"`
652			Enabled  bool   `json:"enabled"`
653			Text     string `json:"text"`
654		}
655		if res.Status != 200 || json.Unmarshal([]byte(res.Body), &p) != nil {
656			return "fail"
657		}
658		if p.Revision != want["revision"] || fmt.Sprint(p.Enabled) != want["enabled"] || p.Text != oq3TextOrEmpty(want["text"]) {
659			return "fail"
660		}
661		return "pass"
662	}
663	
664	func oq3ReloadVerdict(res oq3HTTPResult, want map[string]string) string {
665		if oq3IsHTML(res) || res.Status == http.StatusNotFound {
666			return "absent"
667		}
668		if fmt.Sprint(res.Status) != want["status"] {
669			return "fail"
670		}
671		if want["code"] != "" {
672			var e struct {
673				Error struct {
674					Code string `json:"code"`
675				} `json:"error"`
676			}
677			if json.Unmarshal([]byte(res.Body), &e) != nil || e.Error.Code != want["code"] {
678				return "fail"
679			}
680			return "pass"
681		}
682		var sel struct {
683			Revision   string `json:"revision"`
684			Generation string `json:"generation"`
685		}
686		if json.Unmarshal([]byte(res.Body), &sel) != nil || sel.Revision != want["revision"] || sel.Generation != want["generation"] {
687			return "fail"
688		}
689		return "pass"
690	}
