696	// storeCommitted reads the designated store's current profile (blueprint §3.1 schema) read-only:
697	// "absent" before G1, "pass" when it holds the expected revision, enabled flag and text (review
698	// finding 10: an exit status or a response body alone is not a committed save).
699	func (r *oq3Run) storeCommitted(want map[string]string) string {
700		if _, err := os.Stat(r.storePath()); err != nil {
701			return "absent"
702		}
703		db, err := sql.Open("sqlite3", "file:"+r.storePath()+"?mode=ro")
704		if err != nil {
705			return "fail"
706		}
707		defer db.Close()
708		var rev int64
709		var enabled int
710		var text string
711		if err := db.QueryRow(`SELECT m.current_revision, r.enabled, r.text FROM metadata m JOIN revisions r ON r.revision = m.current_revision WHERE m.id = 1`).Scan(&rev, &enabled, &text); err != nil {
712			return "fail"
713		}
714		if fmt.Sprint(rev) == want["revision"] && fmt.Sprint(enabled == 1) == want["enabled"] && text == oq3TextOrEmpty(want["text"]) {
715			return "pass"
716		}
717		return "fail"
718	}
