720	// storeEvents checks the terminal event sequence of blueprint §3.1: two conversations opened under
721	// distinct identities, and one reload recorded under the SECOND identity, from revision 2 to 3 at
722	// generation 2 (review finding 11: a new binding the runtime never uses would leave the reload on
723	// the first identity).
724	func (r *oq3Run) storeEvents() string {
725		if _, err := os.Stat(r.storePath()); err != nil {
726			return "absent"
727		}
728		db, err := sql.Open("sqlite3", "file:"+r.storePath()+"?mode=ro")
729		if err != nil {
730			return "fail"
731		}
732		defer db.Close()
733		rows, err := db.Query(`SELECT conversation_id, generation, kind, COALESCE(from_revision, -1), to_revision FROM events WHERE namespace = 'terminal' ORDER BY rowid`)
734		if err != nil {
735			return "fail"
736		}
737		defer rows.Close()
738		type ev struct {
739			id       string
740			gen      int
741			kind     string
742			from, to int
743		}
744		var evs []ev
745		for rows.Next() {
746			var e ev
747			if err := rows.Scan(&e.id, &e.gen, &e.kind, &e.from, &e.to); err != nil {
748				return "fail"
749			}
750			evs = append(evs, e)
751		}
752		var opened []ev
753		var reloaded []ev
754		for _, e := range evs {
755			switch e.kind {
756			case "opened":
757				opened = append(opened, e)
758			case "reloaded":
759				reloaded = append(reloaded, e)
760			}
761		}
762		if len(opened) != 2 || len(reloaded) != 1 || opened[0].id == opened[1].id {
763			return "fail"
764		}
765		rl := reloaded[0]
766		if rl.id != opened[1].id || rl.gen != 2 || rl.from != 2 || rl.to != 3 || opened[0].to != 1 || opened[1].to != 2 {
767			return "fail"
768		}
769		return "pass"
770	}
