780		if err != nil {
781			return "fail"
782		}
783		defer db.Close()
784		var n int
785		if err := db.QueryRow(`SELECT COUNT(DISTINCT conversation_id) FROM conversations WHERE namespace = 'terminal'`).Scan(&n); err != nil {
786			return "fail"
787		}
788		min, _ := strconv.Atoi(want["min_terminal"])
789		if n >= min {
790			return "pass"
791		}
792		return "fail"
793	}
