839	// oq3KnownPaths are the daemon endpoints the entry points are known to call: the paths of the fake's
840	// route table (oq3RouteMethods). Anything else is an unclassified request and makes the run invalid
841	// (review finding 4).
842	var oq3KnownPaths = func() map[string]bool {
843		m := map[string]bool{}
844		for p := range oq3RouteMethods {
845			m[p] = true
846		}
847		return m
848	}()
849	
850	// oq3BodyScan scans a request body (review round 2, finding 4; round 3, findings 5 and 6). A JSON body
851	// is walked token by token (oq3JSONScan): every key and string value is seen decoded and in order, a
852	// string that is itself a JSON document is walked in turn, numbers never fail the walk, and duplicate
853	// members are reported, since a decoder that keeps one of them hides the other. A body that is not
854	// JSON is scanned as text. An escape such as \u0053 cannot hide text; encodings other than JSON's
855	// (base64, for example) are not decoded. A JSON body that cannot be walked is reported as an error,
856	// never scanned by a weaker rule instead.
857	func oq3BodyScan(c oq3Capture) (leaks, dups []string, err error) {
858		if len(c.Body) > 0 {
859			leaks, dups, err = oq3JSONScan(c.Body, 0)
860		}
861		if c.RawBody != "" {
862			leaks = append(leaks, oq3StringLeaks(c.RawBody, 0)...)
863		}
864		return leaks, dups, err
865	}
866	
867	// oq3EnvelopeLeaks scans what a request carried besides its body (review round 2, finding 4; round 3,
868	// findings 7 and 8): the decoded path and the raw request target; the query raw, through the partial
869	// map url.ParseQuery returns even with an error, and component by component with each key and value
870	// percent-decoded on its own, so one malformed component cannot hide another; and the scan of the
871	// host, headers and trailers made when the request arrived. Every string goes through the same
872	// scanner as a body string, JSON inside included.
873	func oq3EnvelopeLeaks(c oq3Capture) []string {
874		out := oq3StringLeaks(c.Path, 0)
875		out = append(out, oq3StringLeaks(c.RequestURI, 0)...)
876		if c.Query != "" {
877			out = append(out, oq3StringLeaks(c.Query, 0)...)
878			q, _ := url.ParseQuery(c.Query)
879			for k, vs := range q {
880				out = append(out, oq3StringLeaks(k, 0)...)
881				for _, v := range vs {
882					out = append(out, oq3StringLeaks(v, 0)...)
883				}
884			}
885			for _, part := range strings.FieldsFunc(c.Query, func(r rune) bool { return r == '&' || r == ';' }) {
886				for _, piece := range strings.SplitN(part, "=", 2) {
887					if u, err := url.QueryUnescape(piece); err == nil {
888						out = append(out, oq3StringLeaks(u, 0)...)
889					}
890					if u, err := url.PathUnescape(piece); err == nil {
891						out = append(out, oq3StringLeaks(u, 0)...)
892					}
893				}
894			}
895		}
896		for _, h := range c.HeaderLeaks {
897			out = append(out, "envelope "+h)
898		}
899		return out
900	}
901	
902	func oq3Dedupe(xs []string) []string {
903		seen := map[string]bool{}
904		var out []string
905		for _, x := range xs {
906			if !seen[x] {
907				seen[x] = true
908				out = append(out, x)
909			}
910		}
911		sort.Strings(out)
912		return out
913	}
914	
915	// score attributes every captured request to the step that caused it and scores it.
916	// freeze: when a golden is absent, the observed pre-G1 request becomes the golden (baseline only).
917	func (r *oq3Run) score(goldenDir string, freeze bool, source string) oq3ScenarioResult {
918		res := oq3ScenarioResult{Scenario: r.sc, Events: r.events, Invalid: append([]string(nil), r.invalid...), Sandbox: r.s.root}
919		caps := r.d.snapshot()
920		res.Captures = caps

   917	func (r *oq3Run) score(goldenDir string, freeze bool, source string) oq3ScenarioResult {
   918		res := oq3ScenarioResult{Scenario: r.sc, Events: r.events, Invalid: append([]string(nil), r.invalid...), Sandbox: r.s.root}
   919		caps := r.d.snapshot()
   920		res.Captures = caps
   921		notRun := map[int]bool{}
   922		lastHeld := -1
   923		for _, e := range r.events {
   924			if e.Verdict == "dispatched-held" {
   925				lastHeld = e.Step
   926			}
   927			if e.Verdict == "not-run" || e.Verdict == "harness-failed" {
   928				notRun[e.Step] = true
   929				// A held turn whose completion failed was not measured either.
   930				if (e.Op == "terminal-await" || e.Op == "desktop-await") && lastHeld >= 0 {
   931					notRun[lastHeld] = true
   932				}
   933			}
   934		}
   935		// Captures are grouped by method as well as label and path (review round 2, finding 3); under
   936		// returns every method, for the inference paths where a request with the wrong method is itself an
   937		// incorrect delivery.
   938		type key struct {
   939			label, method, path string
   940		}
   941		byKey := map[key][]oq3Capture{}
   942		for _, c := range caps {
