  1253	// oq3AssertState checks a golden (a pre-G1 request) against the state its step declares:
  1254	// assert_tools ("0" or "some"), assert_model, assert_system ("absent" or "present").
  1255	func oq3AssertState(golden any, args map[string]string) string {
  1256		m, _ := golden.(map[string]any)
  1257		if want := args["assert_tools"]; want != "" {
  1258			tools, _ := m["tools"].([]any)
  1259			if (want == "0") != (len(tools) == 0) {
  1260				return fmt.Sprintf("tools: want %s, request has %d", want, len(tools))
  1261			}
  1262		}
  1263		if want := args["assert_model"]; want != "" {
  1264			if got, _ := m["model"].(string); oq3ModelBase(got) != want {
  1265				return fmt.Sprintf("model: want %s, request has %s", want, got)
  1266			}
  1267		}
  1268		if want := args["assert_system"]; want != "" {
  1269			msgs := oq3Messages(golden)
  1270			has := len(msgs) > 0 && oq3Str(msgs[0], "role") == "system"
  1271			if (want == "present") != has {
  1272				return fmt.Sprintf("system message: want %s", want)
  1273			}
  1274		}
  1275		return ""
  1276	}
