320	// oq3JSONScan walks a JSON document token by token (review round 3, findings 5 and 6), so every
321	// object key and string value is seen decoded and in order, duplicate members included, and numbers
322	// are read as json.Number (a value such as 1e400 cannot make the walk fail). It returns the instruction
323	// markers found, where a string that is itself a JSON document is walked in turn (to depth 4); the
324	// duplicate members found, by object path and key; and an error when the document cannot be walked.
325	func oq3JSONScan(doc []byte, depth int) (leaks, dups []string, err error) {
326		dec := json.NewDecoder(bytes.NewReader(doc))
327		dec.UseNumber()
328		type frame struct {
329			object    bool
330			expectKey bool
331			keys      map[string]bool
332			path      string
333		}
334		var stack []*frame
335		pathOf := func() string {
336			if len(stack) == 0 {
337				return "$"
338			}
339			return stack[len(stack)-1].path
340		}
341		valueDone := func() {
342			if len(stack) > 0 && stack[len(stack)-1].object {
343				stack[len(stack)-1].expectKey = true
344			}
345		}
346		var lastKey string
347		for {
348			tok, terr := dec.Token()
349			if terr == io.EOF {
350				break
351			}
352			if terr != nil {
353				return leaks, dups, terr
354			}
355			switch t := tok.(type) {
356			case json.Delim:
357				switch t {
358				case '{', '[':
359					p := pathOf()
360					if len(stack) > 0 && stack[len(stack)-1].object {
361						p += "." + lastKey
362					} else if len(stack) > 0 {
363						p += "[]"
364					}
365					stack = append(stack, &frame{object: t == '{', expectKey: t == '{', keys: map[string]bool{}, path: p})
366				case '}', ']':
367					stack = stack[:len(stack)-1]
368					valueDone()
369				}
370			case string:
371				if len(stack) > 0 && stack[len(stack)-1].object && stack[len(stack)-1].expectKey {
372					f := stack[len(stack)-1]
373					if f.keys[t] {
374						dups = append(dups, f.path+"."+t)
375					}
376					f.keys[t] = true
377					f.expectKey = false
378					lastKey = t
379					leaks = append(leaks, oq3StringLeaks(t, depth)...)
380					continue
381				}
382				leaks = append(leaks, oq3StringLeaks(t, depth)...)
383				valueDone()
384			default:
385				valueDone()
386			}
387		}
388		if dec.More() {
389			return leaks, dups, fmt.Errorf("more than one JSON value")
390		}
391		return leaks, dups, nil
392	}
