604	func (d *oq3Daemon) record(r *http.Request, body []byte, kind string) {
605		d.mu.Lock()
606		var hold time.Duration
607		defer func() {
608			// A control's delay holds the response back after the request is recorded under the label
609			// current at its arrival (review round 3, finding 1).
610			d.mu.Unlock()
611			if hold > 0 {
612				time.Sleep(hold)
613			}
614		}()
615		d.seq++
616		c := oq3Capture{Seq: d.seq, At: time.Now().Format(time.RFC3339Nano), Method: r.Method, Path: r.URL.Path, Label: d.label, Response: kind,
617			Query: r.URL.RawQuery, Host: r.Host, RequestURI: r.RequestURI}
618		for _, l := range oq3StringLeaks(r.Host, 0) {
619			c.HeaderLeaks = append(c.HeaderLeaks, "Host "+l)
620		}
621		// Trailers are complete here: serve reads the whole body before recording.
622		fields := func(src http.Header, where string) map[string][]string {
623			if len(src) == 0 {
624				return nil
625			}
626			out := map[string][]string{}
627			for name, vals := range src {
628				for _, l := range oq3StringLeaks(name, 0) {
629					c.HeaderLeaks = append(c.HeaderLeaks, where+" name "+l)
630				}
631				for _, v := range vals {
632					for _, l := range oq3StringLeaks(v, 0) {
633						c.HeaderLeaks = append(c.HeaderLeaks, where+" "+name+" "+l)
634					}
635					if oq3CredentialHeader(name) {
636						v = fmt.Sprintf("<redacted %d bytes>", len(v))
637					}
638					out[name] = append(out[name], v)
639				}
640			}
641			return out
642		}
643		c.Headers = fields(r.Header, "header")
644		c.Trailers = fields(r.Trailer, "trailer")
645		sort.Strings(c.HeaderLeaks)
646		if len(body) > 0 {
647			if json.Valid(body) {
648				c.Body = append(json.RawMessage(nil), body...)
649			} else {
650				c.RawBody = string(body)
651			}
652		}
653		d.captures = append(d.captures, c)
654		hold = d.delays[c.Label+" "+c.Method+" "+c.Path]
655	}
