657	func (d *oq3Daemon) serve(w http.ResponseWriter, r *http.Request) {
658		body, _ := io.ReadAll(r.Body)
659		if known, allowed := oq3MethodAllowed(r.URL.Path, r.Method); known && !allowed {
660			// As the real daemon: a registered path with another method is refused, never served.
661			d.record(r, body, "method-not-allowed")
662			w.Header().Set("Allow", strings.Join(oq3RouteMethods[r.URL.Path], ", "))
663			http.Error(w, "405 method not allowed", http.StatusMethodNotAllowed)
664			return
