 26	func oq3Select(all []oq3Scenario, sel string) ([]oq3Scenario, error) {
 27		sel = strings.TrimSpace(sel)
 28		if sel == "" {
 29			return nil, errors.New("empty scenario selection refused")
 30		}
 31		if sel == "all" {
 32			return all, nil
 33		}
 34		byID := map[string]oq3Scenario{}
 35		for _, s := range all {
 36			byID[s.ID] = s
 37		}
 38		var out []oq3Scenario
 39		for _, id := range strings.Split(sel, ",") {
 40			s, ok := byID[strings.TrimSpace(id)]
 41			if !ok {
 42				return nil, fmt.Errorf("unknown scenario %q", id)
 43			}
 44			out = append(out, s)
 45		}
 46		return out, nil
 47	}
