 49	// oq3Completeness checks that every frozen trial of every selected scenario produced delivery
 50	// records (observed or missing) and that every selected scenario produced a result.
 51	func oq3Completeness(selected []oq3Scenario, results []oq3ScenarioResult) []string {
 52		var problems []string
 53		got := map[string]oq3ScenarioResult{}
 54		for _, r := range results {
 55			got[r.Scenario.ID] = r
 56		}
 57		for _, sc := range selected {
 58			r, ok := got[sc.ID]
 59			if !ok {
 60				problems = append(problems, "scenario "+sc.ID+" produced no result")
 61				continue
 62			}
 63			seen := map[string]int{}
 64			for _, d := range r.Deliveries {
 65				seen[d.Trial]++
 66			}
 67			for _, tr := range sc.Trials {
 68				if seen[tr.ID] == 0 {
 69					problems = append(problems, "trial "+tr.ID+" has no delivery record")
 70				}
 71			}
 72		}
 73		return problems
 74	}
