251			m = updated.(chatModel)
252		}
253		if opts.PreloadModel != nil && strings.TrimSpace(opts.Model) != "" && !m.openModelOnInit {
254			m.preloadingModel = strings.TrimSpace(opts.Model)
255		}
256	
257		p := tea.NewProgram(m, tea.WithReportFocus())
258		finalModel, err := p.Run()
259		if err != nil {
260			return nil, err
261		}
262	
263		fm := finalModel.(chatModel)
264		if fm.err != nil {
265			return nil, fm.err
266		}
267		return &Result{ChatID: fm.chatID, Messages: fm.messages}, nil
268	}
