281	func (m chatModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
282		if m.canEditInput() && isShiftEnterCSI(msg) {
283			m.insertInputNewline()
284			return m, nil
285		}
286	
287		switch msg := msg.(type) {
288		case tea.WindowSizeMsg:
289			wasSet := m.width > 0 || m.height > 0
290			resized := wasSet && (m.width != msg.Width || m.height != msg.Height)
291			m.width = msg.Width
292			m.height = msg.Height
293			if resized {
294				return m.withFlowTranscriptRepaint(nil)
295			}
296			return m.withFlowTranscriptFlush(nil)
297	
298		case tea.FocusMsg:
299			return m, nil
300	
301		case chatTickMsg:
302			m.tickActive = false
303			if !m.running && !m.compacting && m.preloadingModel == "" {
304				return m, nil
305			}
306			m.spinner++
307			cmd := m.scheduleTick()
308			return m, cmd
309	
310		case chatModelPreloadDoneMsg:
311			if msg.model != "" && msg.model != m.preloadingModel {
312				return m, nil
313			}
314			m.preloadingModel = ""
315			if msg.err != nil {
316				if isUnsupportedThinkingError(msg.err) && thinkRequestsThinking(m.opts.Think) {
317					m.opts.Think = &api.ThinkValue{Value: false}
318					m.status = fmt.Sprintf("Thinking disabled for %s", msg.model)
319					if msg.model != "" && m.opts.PreloadModel != nil {
320						m.preloadingModel = msg.model
321						return m, tea.Batch(preloadModelCmd(m.ctx, m.opts.PreloadModel, msg.model, m.opts.Think), m.scheduleTick())
322					}
323					return m, nil
324				}
325				if !errors.Is(msg.err, context.Canceled) {
326					m.status = "error"
327					m.entries = append(m.entries, newChatEntry(chatEntry{role: "error", content: fmt.Sprintf("Could not load model: %v", msg.err), err: msg.err.Error()}))
328				}
329				return m, nil
330			}
331			if msg.contextWindowTokens > 0 {
332				m.updateContextWindowTokens(msg.contextWindowTokens)
333			} else {
334				m.refreshContextWindowTokens(msg.model)
335			}
336			return m, nil
337	
338		case chatAgentMsg:
339			printedLines := m.flowPrintedLines
340			var printedTranscript []string
341			if printedLines > 0 {
342				printedTranscript = slices.Clone(m.transcriptLines(m.viewWidth()))
343			}
344			m.applyAgentEvent(msg.event)
345			return m.withFlowTranscriptRefreshAfter(printedTranscript, printedLines, waitForChatMsg(m.events))
346	
347		case chatClipboardErrorMsg:
348			if msg.err != nil {
349				m.status = "copy failed: " + msg.err.Error()
350			}
351			return m, nil
352	
353		case chatApprovalPromptMsg:
354			// Full access may have been enabled while this request was in flight
355			// (the user toggled it on after the agent sent the approval request
356			// but before this buffered message was handled). In that window
357			// togglePermissionMode's auto-resolve sees no open prompt yet, so
358			// short-circuit here rather than surfacing a stale approval prompt.
359			if m.allowAllToolsEnabled() {
360				m.approvalPrompt = &chatApprovalPrompt{request: msg.request, reply: msg.reply}
361				return m.resolveApprovalPrompt(chatApprovalChoice{allow: true, allowAll: true})
362			}
363			printedLines := m.flowPrintedLines
364			var printedTranscript []string
365			if printedLines > 0 {
366				printedTranscript = slices.Clone(m.transcriptLines(m.viewWidth()))
367			}
368			m.modelPicker = nil
369			m.modelPickerModels = nil
370			m.openApprovalPrompt(msg)
560		return copyTextCmd(m.ctx, selected)
561	}
