584		}
585		if m.thinkPicker != nil {
586			return m.updateThinkPicker(msg)
587		}
588		if msg.Type != tea.KeyCtrlC && msg.Type != tea.KeyCtrlD {
589			m.disarmQuit()
590		}
591		if msg.Type != tea.KeyEsc {
592			m.disarmEsc()
593		}
594	
595		switch msg.Type {
596		case tea.KeyCtrlC:
597			return m.updateCtrlC()
598		case tea.KeyCtrlD:
599			return m.updateCtrlD()
600		case tea.KeyEsc:
601			return m.updateEsc()
602		case tea.KeyEnter:
603			if msg.Alt {
604				m.insertInputNewline()
605				return m, nil
606			}
607			if m.applySlashCompletion() {
608				return m, nil
609			}
610			if m.applyMentionCompletion() {
611				return m, nil
612			}
613			return m.handleSubmit()
614		case tea.KeyCtrlJ:
615			m.insertInputNewline()
616			return m, nil
617		case tea.KeyCtrlG:
618			return m, nil
619		case tea.KeyCtrlP:
620			return m.updateUpKey()
621		case tea.KeyCtrlN:
622			return m.updateDownKey()
623		case tea.KeyUp:
624			return m.updateUpKey()
625		case tea.KeyDown:
626			return m.updateDownKey()
627		case tea.KeyLeft:
628			if msg.Alt {
629				m.moveInputCursorWord(-1)
630			} else {
631				m.moveInputCursorHorizontal(-1)
632			}
633		case tea.KeyRight:
634			if msg.Alt {
635				m.moveInputCursorWord(1)
636			} else {
637				m.moveInputCursorHorizontal(1)
638			}
639		case tea.KeyCtrlA:
640			m.moveInputCursorToLineStart()
641		case tea.KeyCtrlE:
642			m.moveInputCursorToLineEnd()
643		case tea.KeyCtrlB:
644			m.moveInputCursorHorizontal(-1)
645		case tea.KeyCtrlF:
646			m.moveInputCursorHorizontal(1)
647		case tea.KeyCtrlLeft:
648			m.moveInputCursorWord(-1)
649		case tea.KeyCtrlRight:
650			m.moveInputCursorWord(1)
651		case tea.KeyPgUp:
652			m.scrollBy(max(1, m.transcriptHeight()-1))
653		case tea.KeyPgDown:
654			m.scrollBy(-max(1, m.transcriptHeight()-1))
655		case tea.KeyHome:
656			m.moveInputCursorToLineStart()
657		case tea.KeyEnd:
658			m.moveInputCursorToLineEnd()
659		case tea.KeyCtrlHome:
660			m.scroll = m.maxScroll()
661		case tea.KeyCtrlEnd:
662			m.scroll = 0
663		case tea.KeyBackspace, tea.KeyCtrlH:
664			m.resetPromptHistoryCursor()
665			if msg.Alt {
666				m.deleteInputWordBackward()
667			} else {
668				m.deleteInputBackward()
669			}
670		case tea.KeyCtrlW:
671			m.resetPromptHistoryCursor()
672			m.deleteInputWordBackward()
673		case tea.KeyCtrlU:
674			m.resetPromptHistoryCursor()
675			m.clearInput()
676		case tea.KeyCtrlK:
677			m.resetPromptHistoryCursor()
678			m.deleteInputForward()
679		case tea.KeyDelete:
680			m.resetPromptHistoryCursor()
681			m.deleteInputForward()
682		case tea.KeyTab:
683			m.applyCompletion()
684		case tea.KeySpace:
685			m.insertInputRunes([]rune{' '})
686		case tea.KeyRunes:
687			if !msg.Alt || !m.handleInputAltRunes(msg.Runes) {
688				m.insertInputRunesFromKey(msg.Runes, msg.Paste)
689			}
690		}
691		return m, nil
692	}
