170		// Cloud models need auth + plan check before switching. If we already
171		// know the badge state from the model list, go directly to the right
172		// prompt — no "checking" spinner.
173		if selected.Cloud && m.opts.CheckCloudModel != nil {
174			switch selected.AvailabilityBadge {
175			case "Sign in required":
176				return m.startCloudAuthSignIn(selected.Name, selected.RequiredPlan, selected.SignInURL)
177			case "Upgrade required":
178				return m.startCloudAuthUpgrade(selected.Name, selected.RequiredPlan)
179			}
180			// Badge is empty — auth is satisfied (confirmed via Whoami when the
181			// list was built). Apply directly.
182		}
183	
184		m.modelPicker = nil
185		m.modelPickerModels = nil
186		m.openModelOnInit = false
187		if err := m.applyModelSelection(selected.Name, true); err != nil {
188			m.entries = append(m.entries, newChatEntry(chatEntry{role: "error", content: fmt.Sprintf("Could not switch model: %v", err), err: err.Error()}))
189			m.status = "error"
190			return m, nil
191		}
192		m.status = "ready"
193		return m, tea.Batch(m.startModelPreload(selected.Name), cloudModelPreflightCmd(m.ctx, m.opts, selected.Name, selected.RequiredPlan))
194	}
