205	func (m *chatModel) applyModelSelection(modelName string, persist bool) error {
206		modelName = strings.TrimSpace(modelName)
207		if modelName == "" {
208			return nil
209		}
210		m.opts.Model = modelName
211		m.opts.ContextWindowTokens = 0
212		if m.opts.ToolRegistryForModel != nil {
213			m.opts.Tools = m.opts.ToolRegistryForModel(m.ctx, modelName)
214		}
215		if m.opts.SystemPromptForModel != nil {
216			m.opts.SystemPrompt = m.opts.SystemPromptForModel(m.ctx, modelName, m.opts.Tools, m.opts.ToolsDisabled)
217		}
218		if m.opts.MultiModalForModel != nil {
219			ctx := m.ctx
220			if ctx == nil {
221				ctx = context.Background()
222			}
223			m.opts.MultiModal = m.opts.MultiModalForModel(ctx, modelName)
224		}
225		m.refreshContextWindowTokens(modelName)
226		m.contextTokens = m.estimatePromptTokens(m.messages, "")
227		m.contextEstimate = true
228		if persist && m.opts.OnModelSelected != nil {
229			ctx := m.ctx
230			if ctx == nil {
231				ctx = context.Background()
232			}
233			return m.opts.OnModelSelected(ctx, modelName)
234		}
235		return nil
236	}
