238	func (m *chatModel) startModelPreload(modelName string) tea.Cmd {
239		modelName = strings.TrimSpace(modelName)
240		if m == nil || modelName == "" || m.opts.PreloadModel == nil {
241			return nil
242		}
243		m.preloadingModel = modelName
244		m.spinner = 0
245		return tea.Batch(preloadModelCmd(m.ctx, m.opts.PreloadModel, modelName, m.opts.Think), m.scheduleTick())
246	}
