   322			if err != nil {
   323				t.Fatal(err)
   324			}
   325			req.Header.Set("Content-Type", "application/json")
   326			for k, v := range header {
   327				req.Header.Set(k, v)
   328			}
   329			resp, err := http.DefaultClient.Do(req)
