   563			}
   564			plain := oq3ANSI.ReplaceAllString(string(raw), "")
   565			ack, prompt := strings.Index(plain, oq3AckMarker), strings.Index(plain, "Approve once")
   566			if len(res.Invalid) != 0 || !handled || ack < 0 || prompt < 0 || ack > prompt {
