   572		// The idle proof (review round 2, finding 5), on the real terminal. The probe must read an idle chat
   573		// as idle, and must not read as idle an open approval prompt after the daemon has fully answered
   574		// every request it was sent (where the round-2 rule, daemon completion and a quiet screen, holds),
   575		// nor a turn the daemon is holding. A command the chat keeps as input while a turn runs must not
   576		// reach the next turn's text.
   577		{
   650			if !oq3WaitFor(30*time.Second, func() bool { return d.completedLabel(label) >= 1 }) || !term.idle(30*time.Second) {
   651				t.Fatalf("idle control: the last turn never became idle")
   652			}
   653			term.typeLine("/bye")
   654			if err, ok := term.waitExit(20 * time.Second); !ok || err != nil {
   655				t.Fatalf("idle control: the session did not exit on /bye: ok=%v err=%v", ok, err)
   656			}
   657			t.Log("idle control: idle at rest; not idle at an approval prompt after the daemon finished, nor during a held turn; a busy command kept as input did not reach the next turn")
   658		}
