   668			d.setToolRounds(oq3Label("RCB", 1, "terminal-turn"), 1) // a tool call the step does not declare, so nothing approves it
   669			run := oq3NewRun(t, sc, d, s)
   670			run.execute()
   671			res := run.score(goldens, true, "runner control")
   672			turnVerdict := ""
   673			for _, e := range res.Events {
   674				if e.Step == 1 {
   675					turnVerdict = e.Verdict
   676				}
   677			}
   678			// The turn itself must fail; a runner that trusted the quiet screen records it as done and
   679			// only fails later, when /bye lands on the approval prompt.
   680			if turnVerdict != "harness-failed" || !strings.Contains(strings.Join(res.Invalid, " | "), "never proved idle") {
   681				t.Fatalf("a turn left waiting after the daemon finished was treated as ended: turn verdict %q, invalid %v", turnVerdict, res.Invalid)
   682			}
   683			t.Logf("runner idle control -> turn %s; invalid: %v", turnVerdict, res.Invalid)
   684		}
