   687		// session that reports context_unavailable naming the daemon's version and exits is a held refusal,
   688		// and its no-dispatch turn is scored as refused as required; a session that exits without that
   689		// report is a harness failure, never a refusal.
   690		for _, mode := range []string{"terminal-refuse-at-start", "terminal-exit-silently", "terminal-banner-then-crash", "terminal-refuse-and-stay"} {
   691			d := oq3StartDaemon(t)
   692			d.noCapability = true
   693			s := oq3NewSandbox(t, "RC-"+mode)
   694			sc := oq3Scenario{ID: "RCR", NoCapability: true, Trials: []oq3Trial{{"RCR-X", famSave, "terminal", "refusal control"}},
   695				Steps: []oq3Step{h("terminal-start"),
   696					{Op: "terminal-turn", Class: "required-no-dispatch", Trial: "RCR-X", Prompt: "OQ3 refusal control turn.", Args: map[string]string{}},
   697					h("terminal-stop")}}
   698			run := oq3NewRun(t, sc, d, s)
   699			run.terminalHelper = mode
   700			run.execute()
   701			res := run.score(goldens, true, "runner control")
   702			switch mode {
   703			case "terminal-refuse-at-start", "terminal-refuse-and-stay":
   704				refused := false
   705				for _, e := range res.Events {
   706					refused = refused || e.Verdict == "refused-at-start"
   707				}
   708				if len(res.Invalid) != 0 || !refused || len(res.Deliveries) != 1 || res.Deliveries[0].Status != "refused-as-required" {
   709					t.Fatalf("a permitted refusal at start-up was not held: invalid %v, events %+v, deliveries %+v", res.Invalid, res.Events, res.Deliveries)
   710				}
   711			case "terminal-exit-silently", "terminal-banner-then-crash":
   712				// Neither is a capability refusal: one reports nothing, the other names the daemon's version
   713				// in a banner and fails for another reason (review round 3, finding 3).
   714				if len(res.Invalid) == 0 {
   715					t.Fatalf("%s passed as a refusal: %+v", mode, res.Deliveries)
   716				}
   717			}
   718			t.Logf("refusal control %-26s -> invalid %v; deliveries %d", mode, res.Invalid, len(res.Deliveries))
   719		}
   720	
   721		// Harness faults on a real desktop scenario: each must make the run invalid, not change the number.
   722		for _, fault := range []string{"malformed-capture", "extra-request", "unknown-label", "none"} {
   723			d := oq3StartDaemon(t)
   724			s := oq3NewSandbox(t, "RC-"+fault)
   725			sc := oq3Scenario{ID: "RC", Trials: []oq3Trial{{"RC-X", famSave, "desktop", ""}},
   726				Steps: []oq3Step{h("desktop-start"), dTurn("RC-X", "X", "OQ3 runner control turn.", nD()), h("desktop-stop")}}
   727			run := oq3NewRun(t, sc, d, s)
   728			run.execute()
   729			label := oq3Label("RC", 1, "desktop-turn")
   730			switch fault {
   731			case "malformed-capture":
   732				d.setLabel(label)
   733				oq3PostRaw(t, d, []byte(`{"model":"oq3-model","messages":[`))
   734			case "extra-request":
   735				d.setLabel(label)
   736				oq3PostRaw(t, d, []byte(`{"model":"oq3-model","messages":[{"role":"user","content":"extra"}]}`))
   737			case "unknown-label":
   738				d.setLabel("RC/99/nowhere")
   739				oq3PostRaw(t, d, []byte(`{"model":"oq3-model","messages":[{"role":"user","content":"stray"}]}`))
   740			}
   741			res := run.score(goldens, true, "runner control")
   742			if fault == "none" {
   743				if len(res.Invalid) != 0 {
   744					t.Fatalf("clean control run invalid: %v", res.Invalid)
   745				}
   746				continue
   747			}
   748			if len(res.Invalid) == 0 {
   749				t.Fatalf("harness fault %s did not make the run invalid", fault)
   750			}
   751			t.Logf("harness fault %-18s -> invalid: %v", fault, res.Invalid)
   752		}
   753	
   754		// A failing child: a terminal session for a model the daemon does not have exits at once; the
   755		// step is a harness failure and the run is invalid, never a missing delivery.
   756		d := oq3StartDaemon(t)
   757		s := oq3NewSandbox(t, "RC-child")
   758		sc := oq3Scenario{ID: "RCC", Trials: []oq3Trial{{"RCC-X", famSave, "terminal", ""}},
   759			Steps: []oq3Step{with(h("terminal-start"), "model", "no-such-model"), tTurn("RCC-X", "OQ3 turn that must not be scored.", nT()), h("terminal-stop")}}
   760		run := oq3NewRun(t, sc, d, s)
   761		run.execute()
   762		res := run.score(goldens, true, "runner control")
   763		if len(res.Invalid) == 0 {
   764			t.Fatal("a failing child process did not make the run invalid")
   765		}
   766		// Review finding 12: steps not run after a harness failure are not measured, never missing.
   767		if sum := oq3Summarise([]oq3ScenarioResult{res}, "control", "failing child", "none"); sum.FailureNumerator != 0 || len(sum.NotMeasured) == 0 {
   768			t.Fatalf("a failing child changed the number: numerator %d, not measured %v", sum.FailureNumerator, sum.NotMeasured)
   769		}
   770		t.Logf("failing child -> invalid: %v; not measured: %v", res.Invalid, res.NotMeasured)
   771	}
