  1481	// oq3Ratio prints an exact fraction and a decimal; a zero denominator is refused, never printed as zero.
  1482	func oq3Ratio(num, den int) string {
  1483		if den == 0 {
  1484			return "undefined (no trials)"
  1485		}
  1486		return fmt.Sprintf("%d/%d = %.4f", num, den, float64(num)/float64(den))
  1487	}
